{
  "findings": [
    {
      "check_id": "CKV2_AWS_6",
      "title": "S3 Bucket Public Access Block Missing",
      "resource": "aws_s3_bucket.flowbucket",
      "severity": "HIGH",
      "explanation": "The S3 bucket does not have a public access block configured, leaving it potentially exposed to unintended public access if bucket policies or ACLs are misconfigured."
    },
    {
      "check_id": "CKV_AWS_145",
      "title": "S3 Bucket Encryption Not Configured",
      "resource": "aws_s3_bucket.flowbucket",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket lacks server-side encryption configuration. Data at rest is not encrypted with KMS or SSE-S3 by default, violating data protection standards."
    },
    {
      "check_id": "CKV_AWS_18",
      "title": "S3 Bucket Access Logging Disabled",
      "resource": "aws_s3_bucket.flowbucket",
      "severity": "MEDIUM",
      "explanation": "Server access logging is not enabled for the bucket, preventing audit trails of requests made against the stored flow logs."
    },
    {
      "check_id": "CKV_AWS_21",
      "title": "S3 Bucket Versioning Disabled",
      "resource": "aws_s3_bucket.flowbucket",
      "severity": "MEDIUM",
      "explanation": "Versioning is not enabled on the bucket, meaning accidental deletion or overwriting of log files cannot be recovered."
    }
  ],
  "patched_code": "resource "aws_s3_bucket" "flowbucket" {
  bucket        = "${local.resource_prefix.value}-flowlogs"
  force_destroy = true
  tags = merge({
    Name        = "${local.resource_prefix.value}-flowlogs"
    Environment = local.resource_prefix.value
    }, {
  })
}

resource "aws_s3_bucket_public_access_block" "flowbucket" {
  bucket = aws_s3_bucket.flowbucket.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "flowbucket" {
  bucket = aws_s3_bucket.flowbucket.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_logging" "flowbucket" {
  bucket = aws_s3_bucket.flowbucket.id

  target_bucket = aws_s3_bucket.flowbucket.id # In production, this should point to a separate secure log bucket
  target_prefix = "log/"
}

resource "aws_s3_bucket_versioning" "flowbucket" {
  bucket = aws_s3_bucket.flowbucket.id
  versioning_configuration {
    status = "Enabled"
  }
}",
  "fix_summary": "Added `aws_s3_bucket_public_access_block` to prevent public exposure, `aws_s3_bucket_server_side_encryption_configuration` to enforce KMS encryption, `aws_s3_bucket_logging` to enable access auditing, and `aws_s3_bucket_versioning` to protect against data loss. Note: The logging target currently points to itself for syntactic validity; in a real environment, this should reference a dedicated, secured log bucket."
}
